// A long, as Avro encodes one: zigzag, then seven bits a byte, low bits first.
inline void put_long(std::string& out, std::int64_t value) {
    auto bits = (static_cast<std::uint64_t>(value) << 1) ^ static_cast<std::uint64_t>(value >> 63);

    while (bits >= 0x80) {
        out.push_back(static_cast<char>((bits & 0x7f) | 0x80));
        bits >>= 7;
    }

    out.push_back(static_cast<char>(bits));
}

// A double, as Avro encodes one: its eight bytes, least significant first.
inline void put_double(std::string& out, double value) {
    std::uint64_t bits = 0;
    std::memcpy(&bits, &value, sizeof bits);

    for (int index = 0; index < 8; ++index) {
        out.push_back(static_cast<char>(bits & 0xff));
        bits >>= 8;
    }
}

// A string or bytes, as Avro encodes either: its length, then itself.
inline void put_bytes(std::string& out, std::string_view value) {
    put_long(out, static_cast<std::int64_t>(value.size()));
    out.append(value);
}

